mapper.select:
select id, name, description, status, version, fcu, fcd, lcu, lcd
from selfcheck_scenario
where id = #{value}

select a.id, a.name, a.description, a.status, a.version, a.fcu, a.fcd, a.lcu, a.lcd, (select count(1) from selfcheck_scenario_item i where i.scenario_id = a.id) as itemCount, case when not exists(select 1 from selfcheck_scenario_item i where i.scenario_id = a.id and i.is_active = 1) then 0 when exists(select 1 from selfcheck_scenario_item i where i.scenario_id = a.id and i.is_active = 1 and i.is_script_valid = 0) then 0 else 1 end as isScriptValid from selfcheck_scenario a
and (a.name like concat('%', #{keyword}, '%') or a.description like concat('%', #{keyword}, '%'))
and a.status = #{status}
order by a.lcd desc, a.id desc limit #{startNum}, #{pageSize}

select count(1) from selfcheck_scenario
and (name like concat('%', #{keyword}, '%') or description like concat('%', #{keyword}, '%'))
and status = #{status}

mapper.update:
update selfcheck_scenario
set status = #{status}, version = version + 1, lcu = #{lcu}, lcd = now()
where id = #{id} and version = #{version}

mapper.select:
select r.id, r.scenario_id as scenarioId, r.scenario_name as scenarioName, r.scenario_version as scenarioVersion, r.trigger_type as triggerType, r.status, r.executor_uuid as executorUuid, u.user_name as userName, r.server_id as serverId, r.item_count as itemCount, r.start_time as startTime, r.end_time as endTime, r.duration_ms as durationMs, r.success_count as successCount, r.failed_count as failedCount, r.error_message as errorMessage, r.fcu, r.fcd from selfcheck_run r left join `user` u on u.uuid = r.executor_uuid
and r.scenario_id = #{scenarioId} and r.status = #{status} and r.scenario_name like concat('%', #{keyword}, '%')
order by r.fcd desc, r.id desc limit #{startNum}, #{pageSize}

select count(1)
from selfcheck_run

    and scenario_id = #{scenarioId}
    and status = #{status}
    and scenario_name like concat('%', #{keyword}, '%')

mapper.update:
update selfcheck_run
set status = #{status}, start_time = #{startTime}, end_time = #{endTime}, duration_ms = #{durationMs},
    running_key = #{runningKey}, item_count = #{itemCount}, success_count = #{successCount},
    failed_count = #{failedCount}, error_message = #{errorMessage}
where id = #{id}

update selfcheck_run_item
set status = #{status}, phase_list = #{phaseList}, response_snapshot = #{responseSnapshot},
    script_result = #{scriptResult}, console_log_list = #{consoleLogList}, diagnostic_list = #{diagnosticList},
    cleanup_status = #{cleanupStatus}, start_time = #{startTime}, end_time = #{endTime},
    duration_ms = #{durationMs}, truncated_field_list = #{truncatedFieldList}, trace_id = #{traceId}
where id = #{id}
